from typing import Callable, Dict, Hashable, List, Set

def bottleneck_distance(
    points: List[Hashable],
    dist: Callable[[Hashable, Hashable], float],
    x: Hashable,
    y: Hashable,
) -> float:
    """Bottleneck (min-max path) distance: the smallest eps at which x and y
    become Rips-connected. Computed by Dijkstra relaxation under the (min, max)
    tropical semiring. Over an ultrametric space this equals dist(x, y)."""
    if x == y:
        return 0.0
    best: Dict[Hashable, float] = {p: float("inf") for p in points}
    best[x] = 0.0
    unvisited: Set[Hashable] = set(points)
    while unvisited:
        u = min(unvisited, key=lambda p: best[p])
        unvisited.remove(u)
        if u == y:
            return best[y]
        for v in unvisited:
            cand = max(best[u], dist(u, v))
            if cand < best[v]:
                best[v] = cand
    return best[y]


def two_adic_distance(a: int, b: int) -> float:
    if a == b:
        return 0.0
    d = abs(a - b); v = 0
    while d % 2 == 0:
        d //= 2; v += 1
    return 2.0 ** (-v)

if __name__ == "__main__":
    pts = list(range(8))
    ok = all(abs(bottleneck_distance(pts, two_adic_distance, x, y) - two_adic_distance(x, y)) < 1e-12
             for x in pts for y in pts if x < y)
    print("bottleneck == dist on 2-adic integers:", ok)
    rpts = [0, 1, 2, 3, 4]
    print("real line bottleneck(0,4) =",
          bottleneck_distance(rpts, lambda a, b: float(abs(a - b)), 0, 4),
          "vs dist = 4")

from typing import Callable, Dict, Hashable, List, Set, Tuple
from itertools import combinations

def connected_components(
    points: List[Hashable],
    dist: Callable[[Hashable, Hashable], float],
    eps: float,
) -> List[Set[Hashable]]:
    """Connected components (pi_0) of the Rips graph at scale eps via union-find.
    Over an ultrametric space each component is exactly a closed eps-ball, and
    the component count equals the number of distinct closed eps-balls."""
    parent: Dict[Hashable, Hashable] = {p: p for p in points}

    def find(p: Hashable) -> Hashable:
        while parent[p] != p:
            parent[p] = parent[parent[p]]
            p = parent[p]
        return p

    def union(p: Hashable, q: Hashable) -> None:
        parent[find(p)] = find(q)

    for x, y in combinations(points, 2):
        if dist(x, y) <= eps:
            union(x, y)
    groups: Dict[Hashable, Set[Hashable]] = {}
    for p in points:
        groups.setdefault(find(p), set()).add(p)
    return list(groups.values())


if __name__ == "__main__":
    labels = ["a", "b", "c", "d"]
    table = {("a","b"):1.0, ("c","d"):2.0, ("a","c"):3.0,
             ("a","d"):3.0, ("b","c"):3.0, ("b","d"):3.0}
    def coph(x, y):
        if x == y: return 0.0
        return table[(x,y)] if (x,y) in table else table[(y,x)]
    for eps in [0.5, 1.0, 2.0, 3.0]:
        comps = connected_components(labels, coph, eps)
        print(f"eps={eps}: {len(comps)} comps", sorted(sorted(c) for c in comps))

